diff --git a/test_fix.go b/test_fix.go
new file mode 100644
index 0000000..2e39524
--- /dev/null
+++ b/test_fix.go
@@ -0,0 +1,22 @@
+package main
+
+import (
+	"fmt"
+	"github.com/RoaringBitmap/roaring/v2"
+)
+
+func main() {
+	// Create a dense bitmap
+	dense := make([]uint64, 10)
+	dense[0] = 0xFFFFFFFFFFFFFFFF // All bits set in first word
+	dense[5] = 0x000000000000FFFF // Some bits set in middle word
+	
+	// This should not cause infinite recursion anymore
+	bitmap := roaring.NewFromDense(dense, false)
+	
+	fmt.Printf("Created bitmap with %d elements\n", bitmap.GetCardinality())
+	
+	// Convert back to dense to verify
+	backToDense := bitmap.ToDense()
+	fmt.Printf("Converted back to dense, length: %d\n", len(backToDense))
+}

